const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const fallback = (section: string): Definition => ({ title: "Workspace", endpoint: `/${section === "admin" ? "internal" : section === "am" ? "assetmgmt" : "quant"}/resources/overview`, hint: "This workspace is ready for a specific merged workflow." });
const fieldsFor = (mode?: Mode) => mode === "dcf" ? ["free_cash_flow", "growth_rate", "discount_rate", "terminal_growth_rate", "shares_outstanding"] : mode === "thesis" ? ["ticker", "bull_case", "bear_case", "catalysts", "valuation_notes", "conviction", "target_price", "holding_period"] : mode === "portfolio" ? ["name", "starting_cash"] : mode === "model" ? ["name", "code"] : mode === "task" ? ["title", "owner_id", "due_at", "reminder_days"] : mode === "recurrence" ? ["rrule", "event_name_template", "task_title", "due_days", "owner_id"] : mode === "pitch" ? ["thesis_id", "department"] : mode === "channel" ? ["name", "ticker"] : mode === "event" ? ["title", "event_at", "event_type_tags", "due_at"] : mode === "deadline" ? ["title", "due_at", "tags"] : mode === "meeting" ? ["title", "meeting_at", "notes", "project_id"] : mode === "announcement" ? ["title", "body", "priority", "audience", "division_id", "project_id", "recipient_ids", "publish_at", "expires_at"] : mode === "template" ? ["title", "event_type_tags"] : mode === "assignment" ? ["name", "priority", "event_type_tags", "assign_capability", "fallback_capability"] : mode === "role" ? ["name", "description", "capabilities"] : mode === "unit" ? ["name", "description"] : ["title", "description"];

async function request(path: string, init?: RequestInit) {
  const response = await fetch(`${api}/api/v1${path}`, { credentials: "include", headers: { "content-type": "application/json", ...(init?.headers ?? {}) }, ...init });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error ?? "Request failed");
  return payload.data;
}

function valueSummary(value: Record<string, unknown>) {
  return String(value.name ?? value.title ?? value.ticker ?? value.id ?? "Record");
}

function backtestMetrics(raw: unknown) {
  const value = raw as Record<string, any>; const performance = value.totalPerformance ?? {}; const portfolio = performance.portfolioStatistics ?? {}; const trades = performance.tradeStatistics ?? {}; const statistics = value.statistics ?? {}; const state = value.state ?? {}; const configuration = value.algorithmConfiguration ?? {}; const number = (input: unknown) => { const parsed = Number(String(input ?? "").replace(/[,$%\s]/g, "")); return Number.isFinite(parsed) ? parsed : null; }; const ratio = (input: unknown) => typeof input === "string" && input.includes("%") ? (number(input) ?? 0) / 100 : number(input); const metric = (key: string, fallback?: string) => portfolio[key] ?? trades[key] ?? statistics[fallback ?? key] ?? null; const date = (...values: unknown[]) => values.map((input) => { const parsed = new Date(String(input ?? "")); return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString(); }).find(Boolean) ?? null;
  const rollingWindow = value.rollingWindow && typeof value.rollingWindow === "object" ? Object.entries(value.rollingWindow as Record<string, any>).reduce<Record<string, { windows: number; average_net_profit: number | null }>>((groups, [key, window]) => { const group = key.split("_")[0] || "other"; const profit = ratio(window?.portfolioStatistics?.totalNetProfit); const current = groups[group] ?? { windows: 0, average_net_profit: null }; groups[group] = { windows: current.windows + 1, average_net_profit: current.average_net_profit === null || profit === null ? profit ?? current.average_net_profit : (current.average_net_profit * current.windows + profit) / (current.windows + 1) }; return groups; }, {}) : {};
  const charts = value.charts && typeof value.charts === "object" ? Object.entries(value.charts as Record<string, any>).reduce<Record<string, unknown>>((manifest, [name, chart]) => { manifest[name] = { name: chart?.name ?? name, chart_type: chart?.chartType ?? null, series_count: Object.keys(chart?.series ?? {}).length }; return manifest; }, {}) : {};
  if (!Object.keys(performance).length || !Object.keys(state).length) throw new Error("Backtest JSON is missing totalPerformance or state");
  return { run_name: state.Name ?? configuration.name ?? "Backtest", status: state.Status ?? null, host_name: state.Hostname ?? null, started_at: date(state.StartTime), ended_at: date(state.EndTime), timeframe_start: date(trades.startDateTime, trades.startDate, configuration.startDate, state.StartDate, state.StartTime), timeframe_end: date(trades.endDateTime, trades.endDate, configuration.endDate, state.EndDate, state.EndTime), starting_capital: number(portfolio.startEquity ?? statistics["Start Equity"]), end_equity: number(portfolio.endEquity ?? statistics["End Equity"]), net_profit: ratio(metric("totalNetProfit", "Net Profit")), annual_return: ratio(metric("compoundingAnnualReturn", "Compounding Annual Return")), drawdown: ratio(metric("drawdown", "Drawdown")), sharpe: number(metric("sharpeRatio", "Sharpe Ratio")), sortino: number(metric("sortinoRatio", "Sortino Ratio")), win_rate: ratio(metric("winRate", "Win Rate")), loss_rate: ratio(metric("lossRate", "Loss Rate")), alpha: number(metric("alpha", "Alpha")), beta: number(metric("beta", "Beta")), total_trades: number(metric("totalNumberOfTrades", "Total Trades")), total_fees: number(metric("totalFees", "Total Fees")), capacity: number(statistics["Estimated Strategy Capacity"]), lowest_capacity_asset: statistics["Lowest Capacity Asset"] ?? null, order_count: number(state.OrderCount ?? statistics["Total Orders"]), log_count: number(state.LogCount), insight_count: number(state.InsightCount), chart_manifest: charts, rolling_window_summary: rollingWindow, analysis: Array.isArray(value.analysis) ? value.analysis : [], algorithm_configuration: configuration, runtime_statistics: value.runtimeStatistics ?? {} };
}

export function WorkspaceClient({ section, slug }: { section: string; slug: string[] }) {
  const resourceId = slug.findLast((part) => uuid.test(part));
  const key = `${section}:${slug.join("-") || "dashboard"}`;
  const definition = definitions[key] ?? definitions[`${section}:${slug[0] || "dashboard"}`] ?? fallback(section);
  if (!resourceId && !slug.length && (section === "am" || section === "admin" || section === "quant")) return <DashboardView section={section} />;
  if (!resourceId && section === "am" && slug[0] === "screener") return <AnalysisWorkbench view="screener" />;
  if (!resourceId && section === "am" && slug[0] === "signals") return <AnalysisWorkbench view="signals" />;
  if (!resourceId && section === "am" && slug[0] === "research" && slug[1] && /^[A-Za-z.]{1,12}$/.test(slug[1])) return <ResearchWorkbench ticker={slug[1].toUpperCase()} />;
  if (definition.mode === "brokerage") return <BrokerageWorkspace />;
  const researchTicker = section === "am" && slug[0] === "research" && slug[1] && /^[A-Za-z.]{1,12}$/.test(slug[1]) ? slug[1].toUpperCase() : null;
  const researchView = researchTicker && ['overview', 'technical', 'earnings', 'headlines', 'competitive', 'corp-structure'].includes(slug[2] ?? '') ? slug[2] : 'overview';
  const endpoint = researchTicker ? `/assetmgmt/analysis/research/${researchTicker}/${researchView}` : resourceId ? `${definition.endpoint.split("?")[0]}/${resourceId}` : definition.endpoint;
  const [rows, setRows] = useState<unknown[]>([]); const [related, setRelated] = useState<unknown[]>([]); const [members, setMembers] = useState<Record<string, unknown>[]>([]); const [theses, setTheses] = useState<Record<string, unknown>[]>([]); const [error, setError] = useState(""); const [loading, setLoading] = useState(true); const [result, setResult] = useState<unknown>(null); const [draft, setDraft] = useState("");
  const formFields = useMemo(() => fieldsFor(definition.mode), [definition.mode]);
  const refresh = async () => {
    setLoading(true); setError("");
    try { const data = await request(endpoint); const records = Array.isArray(data) ? data : [data]; setRows(records); if (resourceId) setDraft(JSON.stringify(records[0] ?? {}, null, 2)); if (!resourceId && definition.mode === "member") setRelated(await request("/auth/invitations")); else if (resourceId && definition.mode === "model") setRelated((await Promise.all([request(`/quant/models/${resourceId}/runs`), request(`/quant/models/${resourceId}/versions`), request(`/quant/artifacts?model_id=${resourceId}`)])).flat()); else if (resourceId && definition.mode === "portfolio") setRelated((await Promise.all([request(`/assetmgmt/portfolios/${resourceId}/positions`), request(`/assetmgmt/portfolios/${resourceId}/trades`), request(`/assetmgmt/portfolios/${resourceId}/orders`)])).flat()); else if (resourceId && definition.mode === "thesis") setRelated(await request(`/assetmgmt/theses/${resourceId}/trades`)); else if (resourceId && (definition.mode === "unit" || definition.mode === "role")) { const links = await request(`/internal/${slug[0]}-members`); const tasks = slug[0] === "projects" ? await request(`/internal/projects/${resourceId}/tasks`) : []; setRelated([...(links as Record<string, unknown>[]).filter((link) => link.parent_id === resourceId), ...(tasks as Record<string, unknown>[])]); } else if (resourceId && definition.mode === "template") { const steps = await request("/internal/workflow-steps"); setRelated((steps as Record<string, unknown>[]).filter((step) => step.template_id === resourceId)); } else if (resourceId && definition.mode === "pitch") { const [votes, channels] = await Promise.all([request("/assetmgmt/pitch-votes"), request("/assetmgmt/channels")]); setRelated([...(votes as Record<string, unknown>[]).filter((vote) => vote.pitch_id === resourceId), ...(channels as Record<string, unknown>[]).filter((channel) => channel.pitch_id === resourceId)]); } else if (resourceId && definition.mode === "channel") { const messages = await request("/assetmgmt/channel-messages"); setRelated((messages as Record<string, unknown>[]).filter((message) => message.channel_id === resourceId)); } else if (resourceId && definition.mode === "meeting") { const [attendance, actions] = await Promise.all([request("/internal/attendance"), request("/internal/action-items")]); setRelated([...(attendance as Record<string, unknown>[]).filter((item) => item.meeting_id === resourceId), ...(actions as Record<string, unknown>[]).filter((item) => item.meeting_id === resourceId)]); } else if (resourceId && definition.mode === "task") { const [comments, reminders] = await Promise.all([request("/internal/comments"), request(`/internal/tasks/${resourceId}/reminders`)]); setRelated([...(comments as Record<string, unknown>[]).filter((comment) => comment.task_id === resourceId), ...(reminders as unknown[])]); } else setRelated([]); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load workspace"); }
    finally { setLoading(false); }
  };
  useEffect(() => { void refresh(); }, [endpoint]);
  useEffect(() => { if (section === "admin") void request("/auth/directory").then((data) => setMembers(data as Record<string, unknown>[])).catch(() => {}); }, [section]);
  useEffect(() => { if (section === "am") void request("/assetmgmt/theses").then((data) => setTheses(data as Record<string, unknown>[])).catch(() => {}); }, [section]);
  async function create(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!definition.create) return;
    const values = Object.fromEntries(new FormData(event.currentTarget)); const body: Record<string, unknown> = { ...values };
    if (definition.mode === "portfolio") body.starting_cash = Number(values.starting_cash || 100000);
    if (definition.mode === "dcf") for (const field of formFields) body[field] = Number(values[field]);
    if (definition.mode === "task") { if (values.due_at) body.due_at = new Date(String(values.due_at)).toISOString(); else delete body.due_at; if (!values.owner_id) delete body.owner_id; body.reminder_days = String(values.reminder_days || "7,3,1").split(",").map(Number).filter((value) => Number.isInteger(value) && value >= 0); }
    if (definition.mode === "recurrence") { body.active = true; body.due_days = Number(values.due_days || 0); if (!values.owner_id) delete body.owner_id; }
    if (definition.mode === "event") { body.event_at = new Date(String(values.event_at)).toISOString(); if (values.due_at) body.due_at = new Date(String(values.due_at)).toISOString(); else delete body.due_at; body.event_type_tags = String(values.event_type_tags || "").split(",").map((tag) => tag.trim()).filter(Boolean); body.auto_create_deadline = true; }
    if (definition.mode === "deadline") { body.due_at = new Date(String(values.due_at)).toISOString(); body.tags = String(values.tags || "").split(",").map((tag) => tag.trim()).filter(Boolean); body.generate_workflow = true; }
    if (definition.mode === "template") body.event_type_tags = String(values.event_type_tags || "").split(",").map((tag) => tag.trim()).filter(Boolean);
    if (definition.mode === "role") body.capabilities = String(values.capabilities || "").split(",").map((capability) => capability.trim()).filter(Boolean);
    if (definition.mode === "assignment") { body.priority = Number(values.priority || 0); body.event_type_tags = String(values.event_type_tags || "").split(",").map((tag) => tag.trim()).filter(Boolean); body.active = true; }
    if (definition.mode === "announcement") { body.audience = String(values.audience || "org").toLowerCase(); body.recipient_ids = String(values.recipient_ids || "").split(",").map((id) => id.trim()).filter(Boolean); if (!values.division_id) delete body.division_id; if (!values.project_id) delete body.project_id; if (values.publish_at) body.publish_at = new Date(String(values.publish_at)).toISOString(); else delete body.publish_at; if (values.expires_at) body.expires_at = new Date(String(values.expires_at)).toISOString(); else delete body.expires_at; }
    try { const data = await request(definition.create, { method: "POST", body: JSON.stringify(body) }); setResult(data); event.currentTarget.reset(); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to create record"); }
  }
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    try { const body = JSON.parse(draft); delete body.id; delete body.created_at; delete body.updated_at; delete body.created_by; const data = await request(endpoint, { method: "PATCH", body: JSON.stringify(body) }); setResult(data); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Invalid JSON or unable to save record"); }
  }
  async function uploadArtifact(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const file = new FormData(event.currentTarget).get("artifact"); if (!(file instanceof File) || !file.size) return setError("Choose an artifact to upload");
    try {
      const intent = await request("/quant/artifacts/upload-url", { method: "POST", body: JSON.stringify({ name: file.name, content_type: file.type || "application/octet-stream" }) });
      const upload = await fetch(intent.upload_url, { method: "PUT", headers: { "content-type": file.type || "application/octet-stream" }, body: file }); if (!upload.ok) throw new Error("Artifact upload failed");
      const record = await request("/quant/artifacts", { method: "POST", body: JSON.stringify({ name: file.name, storage_key: intent.storage_key, metadata: { content_type: file.type, size: file.size } }) }); setResult(record); event.currentTarget.reset();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to upload artifact"); }
  }
  async function importRun(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!resourceId) return; const values = new FormData(event.currentTarget);
    try {
      const file = values.get("backtest"); let artifactKey: string | undefined; let metrics = JSON.parse(String(values.get("metrics") || "{}"));
      if (file instanceof File && file.size) {
        if (!file.name.toLowerCase().endsWith(".json")) throw new Error("Backtest artifacts must be JSON files");
        metrics = backtestMetrics(JSON.parse(await file.text())); if (values.get("timeframe_start")) metrics.timeframe_start = new Date(String(values.get("timeframe_start"))).toISOString(); if (values.get("timeframe_end")) metrics.timeframe_end = new Date(String(values.get("timeframe_end"))).toISOString();
        const intent = await request("/quant/artifacts/upload-url", { method: "POST", body: JSON.stringify({ name: file.name, model_id: resourceId, content_type: file.type || "application/json" }) });
        const upload = await fetch(intent.upload_url, { method: "PUT", headers: { "content-type": file.type || "application/json" }, body: file }); if (!upload.ok) throw new Error("Artifact upload failed");
        artifactKey = intent.storage_key;
        await request("/quant/artifacts", { method: "POST", body: JSON.stringify({ name: file.name, model_id: resourceId, storage_key: artifactKey, metadata: { content_type: file.type || "application/json", size: file.size, metrics } }) });
      }
      const data = await request(`/quant/models/${resourceId}/runs`, { method: "POST", body: JSON.stringify({ period: values.get("period"), metrics, artifact_key: artifactKey || values.get("artifact_key") || undefined }) }); setResult(data); event.currentTarget.reset();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to import backtest"); }
  }
  async function uploadCode(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!resourceId) return; const file = new FormData(event.currentTarget).get("code_file");
    try { if (!(file instanceof File) || !file.size || !file.name.toLowerCase().endsWith(".py")) throw new Error("Choose a Python source file"); const data = await request(`/quant/models/${resourceId}`, { method: "PATCH", body: JSON.stringify({ code: await file.text(), metadata: { source_file: file.name } }) }); setResult(data); event.currentTarget.reset(); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to upload source"); }
  }
  async function comment(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const body = String(new FormData(event.currentTarget).get("body") ?? "").trim(); if (!body) return; try { setResult(await request(`/internal/tasks/${resourceId}/comments`, { method: "POST", body: JSON.stringify({ body }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to post comment"); } }
  async function trade(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const form = new FormData(event.currentTarget); const limitPrice = form.get("limit_price"); const thesisId = form.get("thesis_id"); try { setResult(await request(`/assetmgmt/portfolios/${resourceId}/${limitPrice ? "orders" : "trades"}`, { method: "POST", body: JSON.stringify({ ticker: String(form.get("ticker")).toUpperCase(), side: form.get("side"), shares: Number(form.get("shares")), thesis_id: thesisId || undefined, ...(limitPrice ? { limit_price: Number(limitPrice) } : { price: form.get("price") ? Number(form.get("price")) : undefined }) }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to place order"); } }
  async function cancelOrder(orderId: string) { if (!resourceId) return; try { setResult(await request(`/assetmgmt/portfolios/${resourceId}/orders/${orderId}/cancel`, { method: "POST" })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to cancel order"); } }
  async function resetPortfolio(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const reason = String(new FormData(event.currentTarget).get("reason") ?? "").trim(); if (!reason) return; try { setResult(await request(`/assetmgmt/portfolios/${resourceId}/reset`, { method: "POST", body: JSON.stringify({ reason }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to reset portfolio"); } }
  async function vote(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const form = new FormData(event.currentTarget); try { setResult(await request(`/assetmgmt/pitches/${resourceId}/votes`, { method: "POST", body: JSON.stringify({ choice: form.get("choice"), comment: form.get("comment") || undefined }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to vote"); } }
  async function resolvePitch(status: "approved" | "rejected") { if (!resourceId) return; try { setResult(await request(`/assetmgmt/pitches/${resourceId}`, { method: "PATCH", body: JSON.stringify({ status }) })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to resolve pitch"); } }
  async function message(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const body = String(new FormData(event.currentTarget).get("body") ?? "").trim(); if (!body) return; try { setResult(await request(`/assetmgmt/channels/${resourceId}/messages`, { method: "POST", body: JSON.stringify({ body }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to send message"); } }
  async function invite(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); try { const data = await request("/auth/invitations", { method: "POST", body: JSON.stringify({ email: form.get("email"), expires_in_days: Number(form.get("expires_in_days") || 7) }) }); setResult(data); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to create invitation"); } }
  async function revokeInvite(inviteId: string) { try { setResult(await request(`/auth/invitations/${inviteId}`, { method: "DELETE" })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to revoke invitation"); } }
  async function updateMember(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const form = new FormData(event.currentTarget); try { setResult(await request(`/auth/members/${resourceId}`, { method: "PATCH", body: JSON.stringify({ status: form.get("status"), capabilities: String(form.get("capabilities") || "member").split(",").map((value) => value.trim()).filter(Boolean) }) })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to update member"); } }
  async function attendance(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const form = new FormData(event.currentTarget); try { setResult(await request(`/internal/meetings/${resourceId}/attendance`, { method: "POST", body: JSON.stringify({ member_id: form.get("member_id"), status: form.get("status") }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to record attendance"); } }
  async function actionItem(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const form = new FormData(event.currentTarget); try { setResult(await request(`/internal/meetings/${resourceId}/action-items`, { method: "POST", body: JSON.stringify({ description: form.get("description"), owner_id: form.get("owner_id") || undefined, due_at: form.get("due_at") ? new Date(String(form.get("due_at"))).toISOString() : undefined }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to create action item"); } }
  async function convertAction(actionId: string) { if (!resourceId) return; try { setResult(await request(`/internal/meetings/${resourceId}/action-items/${actionId}/task`, { method: "POST" })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to create task"); } }
  async function announcementAction(action: "read" | "archive" | "pin") { if (!resourceId) return; try { const current = rows[0] as Record<string, unknown> | undefined; const data = action === "pin" ? await request(`/internal/announcements/${resourceId}`, { method: "PATCH", body: JSON.stringify({ is_pinned: !current?.is_pinned }) }) : await request(`/internal/announcements/${resourceId}/${action}`, { method: "POST" }); setResult(data); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to update announcement"); } }
  async function workflowStep(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const form = new FormData(event.currentTarget); try { setResult(await request("/internal/workflow-steps", { method: "POST", body: JSON.stringify({ template_id: resourceId, title: form.get("title"), owner_id: form.get("owner_id") || undefined, capability: form.get("capability") || undefined, due_days: Number(form.get("due_days") || 0), reminder_days: String(form.get("reminder_days") || "7,3,1").split(",").map(Number).filter(Number.isFinite), sort_order: related.length }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to add workflow step"); } }
  async function addMember(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const memberId = new FormData(event.currentTarget).get("member_id"); if (!memberId) return; try { setResult(await request(`/internal/${slug[0]}/${resourceId}/members`, { method: "POST", body: JSON.stringify({ member_id: memberId }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to add member"); } }
  async function removeMember(memberId: string) { if (!resourceId) return; try { setResult(await request(`/internal/${slug[0]}/${resourceId}/members/${memberId}`, { method: "DELETE" })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to remove member"); } }
  async function projectTask(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!resourceId) return; const form = new FormData(event.currentTarget); try { setResult(await request(`/internal/projects/${resourceId}/tasks`, { method: "POST", body: JSON.stringify({ title: form.get("title"), owner_id: form.get("owner_id") || undefined, due_at: form.get("due_at") ? new Date(String(form.get("due_at"))).toISOString() : undefined }) })); event.currentTarget.reset(); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to create project task"); } }
  function downloadCode() { const model = rows[0] as Record<string, unknown> | undefined; const code = typeof model?.code === "string" ? model.code : ""; const url = URL.createObjectURL(new Blob([code], { type: "text/x-python" })); const link = document.createElement("a"); link.href = url; link.download = `${String(model?.name ?? "model").replace(/[^A-Za-z0-9._-]/g, "-")}.py`; link.click(); URL.revokeObjectURL(url); }
  async function downloadArtifact(id: string, name: string) { try { const { download_url } = await request(`/quant/artifacts/${id}/download-url`); const link = document.createElement("a"); link.href = download_url; link.download = name; link.click(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to download artifact"); } }
  async function deleteRun(runId: string) { if (!resourceId) return; try { setResult(await request(`/quant/models/${resourceId}/runs/${runId}`, { method: "DELETE" })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to delete imported run"); } }
  async function act(path: string) { try { setResult(await request(path, { method: "POST" })); await refresh(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to complete action"); } }
  const canEdit = definition.editable !== false && Boolean(resourceId);
  return <section className="pt-8">
    <div className="border-b border-white/15 pb-7"><p className="mb-3 text-[10px] font-bold tracking-[.22em] text-[#c79a3b]">LIVE WORKSPACE</p><h2 className="text-4xl leading-none">{definition.title}</h2><p className="mt-4 max-w-2xl leading-6 text-white/60">{definition.hint}</p></div>
    {researchTicker && <nav className="mt-5 flex flex-wrap gap-2 text-[10px] font-bold tracking-[.14em]">{['overview', 'technical', 'earnings', 'headlines', 'competitive', 'corp-structure'].map((view) => <a key={view} href={`/internal/am/research/${researchTicker}/${view}`} className={`border px-3 py-2 ${researchView === view ? 'border-[#c79a3b] text-[#c79a3b]' : 'border-white/20 text-white/60 hover:border-white'}`}>{view.toUpperCase()}</a>)}</nav>}
    {!resourceId && definition.mode === "artifact" && <form onSubmit={uploadArtifact} className="mt-7 flex flex-wrap items-end gap-3 border border-white/15 bg-white/5 p-5"><label className="min-w-72 flex-1 text-[10px] font-bold tracking-[.14em] text-white/55">ARTIFACT FILE<input required name="artifact" type="file" className="mt-2 block w-full border border-white/20 bg-[#101010] p-2 text-sm font-normal tracking-normal text-white" /></label><button className="bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010]">UPLOAD</button></form>}
    {!resourceId && definition.create && <form onSubmit={create} className="mt-7 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-2">{formFields.map((field) => <label key={field} className="text-[10px] font-bold tracking-[.14em] text-white/55">{field.replaceAll("_", " ").toUpperCase()}{field === "owner_id" ? <select name={field} className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="">Unassigned</option>{members.map((member) => <option key={String(member.id)} value={String(member.id)}>{String(member.display_name)}</option>)}</select> : <input required={(definition.mode !== "task" && definition.mode !== "recurrence" && !(definition.mode === "event" && field === "due_at") && !(definition.mode === "announcement" && ["division_id", "project_id", "recipient_ids"].includes(field)) && !(definition.mode === "meeting" && ["notes", "project_id"].includes(field))) || field === "title" || field === "rrule" || field === "event_name_template"} name={field} defaultValue={field === "reminder_days" ? "7,3,1" : field === "event_name_template" ? "Recurring event {date}" : field === "due_days" ? "0" : field === "audience" ? "org" : undefined} placeholder={field === "rrule" ? "FREQ=WEEKLY;BYDAY=MO" : field === "event_type_tags" || field === "tags" ? "finance, marketing" : field === "recipient_ids" ? "member UUIDs, comma separated" : undefined} type={field === "due_at" || field === "event_at" ? "datetime-local" : field.includes("rate") || field.includes("cash") || field.includes("shares") || field === "due_days" ? "number" : "text"} step="any" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white outline-none focus:border-[#c79a3b]" />}</label>)}<button className="self-end bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010] md:col-span-2">{definition.mode === "dcf" ? "CALCULATE" : definition.mode === "event" ? "CREATE EVENT & WORKFLOW" : definition.mode === "deadline" ? "CREATE DEADLINE & WORKFLOW" : "CREATE"}</button></form>}
    {error && <p role="alert" className="mt-5 border-l-2 border-[#ff9f7d] bg-white/5 p-4 text-sm text-[#ffb19a]">{error}</p>}
    {result !== null && <pre className="mt-5 overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-[#c79a3b]">{JSON.stringify(result, null, 2)}</pre>}
    {resourceId && definition.mode === "model" && <form onSubmit={importRun} className="mt-7 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-2"><label className="text-[10px] font-bold tracking-[.14em] text-white/55">PERIOD<select name="period" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="seen">Seen</option><option value="unseen">Unseen</option></select></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">BACKTEST JSON<input name="backtest" type="file" accept="application/json,.json" className="mt-2 block w-full border border-white/20 bg-[#101010] p-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">TIMEFRAME START (OPTIONAL)<input name="timeframe_start" type="datetime-local" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">TIMEFRAME END (OPTIONAL)<input name="timeframe_end" type="datetime-local" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">ARTIFACT KEY (OPTIONAL)<input name="artifact_key" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">METRICS JSON (OPTIONAL)<textarea name="metrics" defaultValue="{}" className="mt-2 min-h-24 w-full border border-white/20 bg-[#101010] p-3 font-mono text-xs font-normal tracking-normal text-white" /></label><button className="bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010] md:col-span-2">IMPORT RUN</button></form>}
    {resourceId && definition.mode === "model" && <form onSubmit={uploadCode} className="mt-3 flex flex-wrap items-end gap-3 border border-white/15 bg-white/5 p-5"><label className="min-w-72 flex-1 text-[10px] font-bold tracking-[.14em] text-white/55">PYTHON SOURCE<input required name="code_file" type="file" accept="text/x-python,.py" className="mt-2 block w-full border border-white/20 bg-[#101010] p-2 text-sm font-normal tracking-normal text-white" /></label><button className="bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010]">UPLOAD SOURCE</button></form>}
    {resourceId && definition.mode === "task" && <><div className="mt-5 flex gap-2"><button onClick={() => act(`/internal/tasks/${resourceId}/start`)} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">START</button><button onClick={() => act(`/internal/tasks/${resourceId}/complete`)} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">COMPLETE</button><button onClick={() => act(`/internal/tasks/${resourceId}/block`)} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">BLOCK</button></div><form onSubmit={comment} className="mt-3 flex gap-3 border border-white/15 bg-white/5 p-4"><input required name="body" placeholder="Add a task comment" className="min-w-0 flex-1 bg-transparent text-sm outline-none" /><button className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">COMMENT</button></form><div className="mt-3 grid gap-3 md:grid-cols-2">{related.map((item, index) => <pre key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{JSON.stringify(item, null, 2)}</pre>)}</div></>}
    {resourceId && definition.mode === "portfolio" && <><form onSubmit={trade} className="mt-5 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-4"><label className="text-[10px] font-bold tracking-[.14em] text-white/55">TICKER<input required name="ticker" maxLength={12} className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">SIDE<select name="side" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="buy">Buy</option><option value="sell">Sell</option></select></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">SHARES<input required name="shares" type="number" min="0.000001" step="any" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">MARKET PRICE (OPTIONAL)<input name="price" type="number" min="0.000001" step="any" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">LIMIT PRICE (OPTIONAL)<input name="limit_price" type="number" min="0.000001" step="any" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">THESIS (OPTIONAL)<select name="thesis_id" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="">No thesis</option>{theses.map((thesis) => <option key={String(thesis.id)} value={String(thesis.id)}>{String(thesis.ticker)} · {String(thesis.status)}</option>)}</select></label><button className="bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010] md:col-span-4">PLACE MARKET / LIMIT ORDER</button></form><form onSubmit={resetPortfolio} className="mt-3 flex gap-3 border border-[#ff9f7d]/40 bg-white/5 p-4"><input required name="reason" placeholder="Admin reset reason" className="min-w-0 flex-1 bg-transparent text-sm outline-none" /><button className="border border-[#ff9f7d] px-3 py-2 text-xs font-bold tracking-[.12em] text-[#ffb19a]">RESET PORTFOLIO</button></form><div className="mt-3 grid gap-3 md:grid-cols-2">{related.map((item, index) => { const value = item as Record<string, unknown>; return <div key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{value.order_type === "limit" && value.status === "pending" && <button onClick={() => cancelOrder(String(value.id))} className="mb-3 border border-white/25 px-2 py-1 text-[10px] font-bold tracking-[.1em] hover:border-[#ff9f7d]">CANCEL LIMIT ORDER</button>}<pre>{JSON.stringify(item, null, 2)}</pre></div>; })}</div></>}
    {resourceId && definition.mode === "pitch" && <><div className="mt-5 flex gap-2"><button onClick={() => resolvePitch("approved")} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">APPROVE</button><button onClick={() => resolvePitch("rejected")} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">REJECT</button></div><form onSubmit={vote} className="mt-3 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-2"><label className="text-[10px] font-bold tracking-[.14em] text-white/55">VOTE<select name="choice" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="for">For</option><option value="against">Against</option><option value="abstain">Abstain</option></select></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">COMMENT<input name="comment" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><button className="bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010] md:col-span-2">SUBMIT VOTE</button></form><div className="mt-3 grid gap-3 md:grid-cols-2">{related.map((item, index) => <pre key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{JSON.stringify(item, null, 2)}</pre>)}</div></>}
    {resourceId && definition.mode === "channel" && <><form onSubmit={message} className="mt-5 flex gap-3 border border-white/15 bg-white/5 p-4"><input required name="body" placeholder="Write a message" className="min-w-0 flex-1 bg-transparent text-sm outline-none" /><button className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">SEND</button></form><div className="mt-3 grid gap-3">{related.map((item, index) => <pre key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{JSON.stringify(item, null, 2)}</pre>)}</div></>}
    {definition.mode === "member" && !resourceId && <><form onSubmit={invite} className="mt-5 flex flex-wrap items-end gap-3 border border-white/15 bg-white/5 p-5"><label className="min-w-72 flex-1 text-[10px] font-bold tracking-[.14em] text-white/55">INVITE EMAIL<input required name="email" type="email" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">EXPIRES DAYS<input name="expires_in_days" defaultValue="7" type="number" min="1" max="30" className="mt-2 w-28 border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><button className="bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010]">CREATE INVITE</button></form><div className="mt-3 grid gap-3">{related.map((item, index) => { const invite = item as Record<string, unknown>; return <div key={index} className="flex items-center justify-between gap-3 border border-white/15 bg-white/5 p-4 text-xs text-white/70"><span>{String(invite.email)} · {String(invite.status)} · expires {String(invite.expires_at)}</span>{invite.status === "pending" && <button onClick={() => revokeInvite(String(invite.id))} className="border border-white/25 px-2 py-1 text-[10px] font-bold tracking-[.1em] hover:border-[#ff9f7d]">REVOKE</button>}</div>; })}</div></>}
    {resourceId && definition.mode === "member" && <form onSubmit={updateMember} className="mt-5 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-2"><label className="text-[10px] font-bold tracking-[.14em] text-white/55">STATUS<select name="status" defaultValue={String((rows[0] as Record<string, unknown> | undefined)?.status ?? "active")} className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">CAPABILITIES<input name="capabilities" defaultValue={Array.isArray((rows[0] as Record<string, unknown> | undefined)?.capabilities) ? ((rows[0] as Record<string, unknown>).capabilities as string[]).join(", ") : "member"} className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><button className="bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010] md:col-span-2">SAVE MEMBER</button></form>}
    {resourceId && definition.mode === "meeting" && <><form onSubmit={attendance} className="mt-5 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-3"><label className="text-[10px] font-bold tracking-[.14em] text-white/55">MEMBER<select required name="member_id" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="">Select member</option>{members.map((member) => <option key={String(member.id)} value={String(member.id)}>{String(member.display_name)}</option>)}</select></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">STATUS<select name="status" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="present">Present</option><option value="absent">Absent</option><option value="excused">Excused</option></select></label><button className="self-end border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">RECORD ATTENDANCE</button></form><form onSubmit={actionItem} className="mt-3 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-3"><label className="text-[10px] font-bold tracking-[.14em] text-white/55 md:col-span-3">ACTION ITEM<input required name="description" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">OWNER<select name="owner_id" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="">Unassigned</option>{members.map((member) => <option key={String(member.id)} value={String(member.id)}>{String(member.display_name)}</option>)}</select></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">DUE<input name="due_at" type="datetime-local" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><button className="self-end bg-[#c79a3b] px-3 py-2 text-xs font-bold tracking-[.12em] text-[#101010]">ADD ACTION</button></form><div className="mt-3 grid gap-3 md:grid-cols-2">{related.map((item, index) => { const value = item as Record<string, unknown>; return <div key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{typeof value.description === "string" && !value.task_id && <button onClick={() => convertAction(String(value.id))} className="mb-3 border border-white/25 px-2 py-1 text-[10px] font-bold tracking-[.1em] hover:border-[#c79a3b]">MAKE TASK</button>}<pre>{JSON.stringify(item, null, 2)}</pre></div>; })}</div></>}
    {resourceId && definition.mode === "announcement" && <div className="mt-5 flex gap-2"><button onClick={() => announcementAction("read")} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">MARK READ</button><button onClick={() => announcementAction("pin")} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">PIN / UNPIN</button><button onClick={() => announcementAction("archive")} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#ff9f7d]">ARCHIVE</button></div>}
    {resourceId && definition.mode === "template" && <><form onSubmit={workflowStep} className="mt-5 grid gap-3 border border-white/15 bg-white/5 p-5 md:grid-cols-2"><label className="text-[10px] font-bold tracking-[.14em] text-white/55">TASK TITLE<input required name="title" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">OWNER (OPTIONAL)<select name="owner_id" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white"><option value="">Resolve by capability</option>{members.map((member) => <option key={String(member.id)} value={String(member.id)}>{String(member.display_name)}</option>)}</select></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">CAPABILITY<input name="capability" placeholder="finance, exec, marketing" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">DUE OFFSET DAYS<input name="due_days" defaultValue="0" type="number" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><label className="text-[10px] font-bold tracking-[.14em] text-white/55">REMINDERS<input name="reminder_days" defaultValue="7,3,1" className="mt-2 w-full border border-white/20 bg-[#101010] px-3 py-2 text-sm font-normal tracking-normal text-white" /></label><button className="bg-[#c79a3b] px-3 py-2 text-xs font-bold tracking-[.12em] text-[#101010] md:col-span-2">ADD STEP</button></form><div className="mt-3 grid gap-3">{related.map((item, index) => <pre key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{JSON.stringify(item, null, 2)}</pre>)}</div></>}
    {resourceId && (definition.mode === "unit" || definition.mode === "role") && <><form onSubmit={addMember} className="mt-5 flex gap-3 border border-white/15 bg-white/5 p-5"><select required name="member_id" className="min-w-0 flex-1 border border-white/20 bg-[#101010] px-3 py-2 text-sm text-white"><option value="">Add member</option>{members.map((member) => <option key={String(member.id)} value={String(member.id)}>{String(member.display_name)}</option>)}</select><button className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">ADD MEMBER</button></form>{slug[0] === "projects" && <form onSubmit={projectTask} className="mt-3 grid gap-3 border border-white/15 bg-white/5 p-4 md:grid-cols-3"><input required name="title" placeholder="Project task" className="border border-white/20 bg-[#101010] px-3 py-2 text-sm text-white" /><select name="owner_id" className="border border-white/20 bg-[#101010] px-3 py-2 text-sm text-white"><option value="">Unassigned</option>{members.map((member) => <option key={String(member.id)} value={String(member.id)}>{String(member.display_name)}</option>)}</select><input name="due_at" type="datetime-local" className="border border-white/20 bg-[#101010] px-3 py-2 text-sm text-white" /><button className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b] md:col-span-3">ADD PROJECT TASK</button></form>}<div className="mt-3 grid gap-3">{related.map((item, index) => { const value = item as Record<string, unknown>; const member = members.find((candidate) => candidate.id === value.member_id); return value.member_id ? <div key={index} className="flex items-center justify-between gap-3 border border-white/15 bg-white/5 p-4 text-xs text-white/70"><span>{member ? String(member.display_name) : String(value.member_id)}</span><button onClick={() => removeMember(String(value.member_id))} className="border border-white/25 px-2 py-1 text-[10px] font-bold tracking-[.1em] hover:border-[#ff9f7d]">REMOVE</button></div> : <pre key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{JSON.stringify(item, null, 2)}</pre>; })}</div></>}
    {resourceId && definition.mode === "model" && <><div className="mt-3 flex gap-2"><button onClick={downloadCode} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">DOWNLOAD SOURCE</button><button onClick={() => act(`/quant/models/${resourceId}/fork`)} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">FORK MODEL</button><button onClick={() => act(`/quant/models/${resourceId}/archive`)} className="border border-white/25 px-3 py-2 text-xs font-bold tracking-[.12em] hover:border-[#c79a3b]">ARCHIVE</button></div><div className="mt-5 grid gap-3 md:grid-cols-2">{related.map((item, index) => { const value = item as Record<string, unknown>; return <div key={index} className="overflow-auto border border-white/15 bg-white/5 p-4 text-xs text-white/70">{typeof value.storage_key === "string" && <button onClick={() => downloadArtifact(String(value.id), String(value.name))} className="mb-3 border border-white/25 px-2 py-1 text-[10px] font-bold tracking-[.1em] hover:border-[#c79a3b]">DOWNLOAD ARTIFACT</button>}{typeof value.period === "string" && <button onClick={() => deleteRun(String(value.id))} className="mb-3 ml-2 border border-white/25 px-2 py-1 text-[10px] font-bold tracking-[.1em] hover:border-[#ff9f7d]">DELETE RUN</button>}<pre>{JSON.stringify(item, null, 2)}</pre></div>; })}</div></>}
    {canEdit && <form onSubmit={save} className="mt-7 border border-white/15 bg-white/5 p-5"><label className="text-[10px] font-bold tracking-[.14em] text-white/55">RECORD JSON<textarea value={draft} onChange={(event) => setDraft(event.target.value)} className="mt-2 min-h-72 w-full border border-white/20 bg-[#101010] p-3 font-mono text-xs font-normal tracking-normal text-white outline-none focus:border-[#c79a3b]" /></label><button className="mt-3 bg-[#c79a3b] px-4 py-3 text-xs font-bold tracking-[.15em] text-[#101010]">SAVE CHANGES</button></form>}
    {definition.mode === "task" && !resourceId && <div className="mt-7 grid gap-3">{rows.map((row, index) => { const task = row as Record<string, unknown>; const id = typeof task.id === "string" && uuid.test(task.id) ? task.id : null; const action = task.status === "done" ? "reopen" : task.status === "blocked" ? "start" : task.status === "in_progress" ? "complete" : "start"; return <div key={String(task.id ?? index)} className="flex flex-wrap items-center justify-between gap-3 border border-white/15 bg-white/5 p-4"><div><p className="font-medium">{String(task.title ?? "Untitled task")}</p><p className="mt-1 text-xs text-white/55">{String(task.status ?? "open").replaceAll("_", " ")} {task.due_at ? `· due ${new Date(String(task.due_at)).toLocaleString()}` : ""}</p></div><div className="flex gap-2"><button onClick={() => id && act(`/internal/tasks/${id}/${action}`)} className="border border-white/25 px-3 py-2 text-[10px] font-bold tracking-[.12em] hover:border-[#c79a3b]">{action.toUpperCase()}</button>{task.status !== "done" && <button onClick={() => id && act(`/internal/tasks/${id}/block`)} className="border border-white/25 px-3 py-2 text-[10px] font-bold tracking-[.12em] hover:border-[#c79a3b]">BLOCK</button>}</div></div>; })}</div>}
    {key === "quant:seen-unseen-comparison" && <div className="mt-7 grid gap-4 md:grid-cols-2">{rows.map((row, index) => { const model = row as Record<string, unknown>; return <article key={String(model.id ?? index)} className="border border-white/15 bg-white/5 p-5"><a href={`/internal/quant/model-library/${model.id}`} className="text-lg font-medium underline decoration-[#c79a3b] underline-offset-4">{String(model.name)}</a><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><p className="mb-2 font-bold tracking-[.12em] text-[#c79a3b]">SEEN</p><pre className="overflow-auto text-white/65">{JSON.stringify(model.seen_metrics ?? "No imported run", null, 2)}</pre></div><div><p className="mb-2 font-bold tracking-[.12em] text-[#c79a3b]">UNSEEN</p><pre className="overflow-auto text-white/65">{JSON.stringify(model.unseen_metrics ?? "No imported run", null, 2)}</pre></div></div></article>; })}</div>}
    <WorkspaceCards rows={rows} section={section} resource={slug[0] ?? "dashboard"} loading={loading} />
  </section>;
}
